INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(49500, 0, 495, 0, 0, 13, 'Howling Fjord', 'The Howling Fjord is the southeastern doorway to Northrend, a land of deep sea inlets, pine forest and sheer bluffs. It is the home of the vrykul, giants of whom there had been no sign for centuries and who have now woken in great numbers. The Dragonflayer clan makes war from Utgarde Keep and its villages, with proto-drakes in the air and harpoon guns on the cliffs, while the Winterskorn hold Skorn and Baleheim. The Scourge walks here too, its necromancers busy among the vrykul at Gjalerbron. Into this the Alliance has come by sea to Valgarde and up the western cliffs to Westguard Keep, and the Forsaken of the Royal Apothecary Society have built Vengeance Landing and New Agamand to test a plague of their own. The taunka of Camp Winterhoof prepare to leave for the north, tuskarr fish from Kamagua on the Isle of Spears, pirates prowl the southwestern reefs, and iron dwarves have seized the old dig sites on the eastern bluffs.', 'warcraft.wiki.gg/wiki/Howling_Fjord (southeastern Northrend, home of the vrykul, Alliance and Forsaken settlements); quest 11295 description (no sign of vrykul activity in their lands for centuries); quest 11254 reward text (Dragonflayer and Winterskorn villages); quest 11236 description (Scourge necromancers at Gjalerbron); quest 11167 description (Royal Apothecary Society brings its plague north); Ashtotem npc_text 11688 (taunka leaving north); quest 11456 description (Kamagua tuskarr); quest 11463 description (Northsea Freebooters); quest 11474 description (iron dwarves on the bluffs); quest 11427 description (harpoon attacks on frigates); quest 11157 (proto-drakes)'),
(49501, 1, 495, 1, 0, 13, 'Valgarde', 'Valgarde is the Alliance port on Daggercap Bay, built with bare hands, blood and tears, as Vice Admiral Keller puts it. It is one of only two safe harbors the Alliance holds in Northrend, and with it runs the main supply line into the continent. The port has been on the defensive since the vrykul first struck it, and Dragonflayer raiders and their worgs still hammer at the gate while proto-drakes circle overhead. Within the walls the Explorers'' League, the draenei seer Thoralius the Wise and Lord Irulon Trueblade of the Argent Crusade keep their posts.', 'Keller npc_text 12097 (built with our bare hands, blood and tears); quest 11228 reward text (one of two safe harbors, the other in the Borean Tundra); quest 11243 description (primary supply line); quest 11244 description (a month after arrival; archaeology team lost; townsfolk taken to the ruins); quest 11228 description (monsters flying overhead); zone_areas 3981: Keller, McSorf, Thoralius, Irulon Trueblade, Cleric of the Crusade, Valgarde Defenders; warcraft.wiki.gg/wiki/Valgarde (Northspear from Menethil); creature display 21947 (Thoralius: draenei)'),
(49502, 1, 495, 2, 0, 13, 'Wyrmskull Village', 'North of Valgarde the Dragonflayer vrykul have made their home among the old ruins of Wyrmskull. Worgs prowl a pit at the heart of the village, harpooners man the docks by the longhouses, and in a cave beside the pit dwells the mystic Yanis, herald of Ingvar the Plunderer. The bodies of Valgarde''s defenders lie where they fell. A bridge over the worg pit leads to the tunnel down into the Utgarde Catacombs, where the Dragonflayers set captives against their gladiators in the Ring of Judgement and dump the losers in the depths for Scourge necromancers to raise as ghouls.', 'quest 11274 description (beast-men in the ruins of Wyrmskull); quest 11290 description (Yanis in a cave next to the worg pit); creature_template 23932 Yanis the Mystic, Herald of Ingvar; quest 11426 description (harpoon operators on the east side docks by the longhouses); Defender Mordun npc_text 11667 (corpses of my best men); quest 11276 description (bridge over the worg pit to the catacombs); quest 11277 description (gladiators; losers turned into ghouls by Scourge necromancers); zone_areas 3982'),
(49503, 1, 495, 3, 0, 13, 'Utgarde Keep', 'Utgarde Keep rises in the heart of the fjord, the stronghold from which the Dragonflayer vrykul make war. Its master is Ingvar the Plunderer, the champion these fearless giants esteem above all, and from its walls his raiders and proto-drake riders go out against Valgarde and Vengeance Landing alike, so that both towns would gladly see him dead. Beneath the keep run the Utgarde Catacombs, reached from Wyrmskull Village, and above it, at the top of the crag, lies Utgarde Pinnacle, the higher hall of the vrykul.', 'quest 11252 description (vrykul esteem Ingvar; bring him down and break their spirit) and 11262 description (Horde: bring down their leader), instance quests used as sources only; quest 13245 description (Ingvar would sack the nearby Alliance and Horde towns), source only; quest 11436 reward text (the Dragonflayer leader, Ingvar); warcraft.wiki.gg/wiki/Utgarde_Keep (Dragonflayer seat; proto-drakes against Valgarde and Vengeance Landing; Pinnacle above); quest 11276 description (catacombs reached by the bridge over the Wyrmskull worg pit); WMOAreaTable.dbc: WMO 4932 (vmaps Valgarde.wmo.vmo) groups -1, 22704, 22937, 22962-22969 and the catacomb and Ring of Judgement groups 22979-22984 map to area 3983; vmap tiles 571_40-42_29-30 place it on map 571 with name set 1 near 1155,-4901'),
(49504, 1, 495, 4, 0, 13, 'Nifflevar', 'Nifflevar stands on the bluffs northeast of Wyrmskull, a Dragonflayer village built around great harpoon guns. Most of the harpoon attacks on Alliance frigates in Daggercap Bay are launched from here, and Dragonflayer warriors, rune-seers and hunting hounds guard the heights. From nearby Ghostblade Post the Forsaken watch the village and wait for reinforcements from Vengeance Landing, meaning to take it before the Alliance can, while a Forsaken scribe frets that the vrykul learning kept here will burn with it.', 'quest 11427 description (Nifflevar, origin of most harpoon attacks on frigates); quest 11344 description (Nifflevar on the bluffs, up through the dam northeast of Wyrmskull); quest 12482 description (Areiel awaits reinforcements; capture before the Alliance); quest 11423 description (Seguine; the town will soon be razed; sagas); zone_areas 3984 (Dragonflayer Warrior, Rune-Seer, Hunting Hound; harpoon guns)'),
(49505, 1, 495, 5, 0, 13, 'Vengeance Landing', 'Vengeance Landing clings to the cliffs of the fjord''s eastern shore, the Forsaken port in Northrend, reached by zeppelin from Tirisfal and joined to the land above by a great lift. High Executor Anselm commands it, and every soldier here has come for one reason: to see Arthas killed. Cannons guard the docks, bat handlers fly riders over the fjord, and the kennel keeper Pontius raises plaguehounds, since living dogs will no longer come near him. In its laboratory the Royal Apothecary Society works on the plague it has brought north for the Scourge, complaining that the strains sent from the Undercity keep failing.', 'Anselm npc_text 11796 (every Forsaken soldier here has come for one reason: Arthas must be killed); Pontius npc_text 12103; Lysander npc_text 11384 and creature_text 24126 group 6 (strains from Undercity failing); quest 11304 description (equipment not the best at a military outpost); zone_areas 4000 (Vengeance Landing Cannoneer, Bat Handler Camille, Drenk Spannerspark Tirisfal Glades Zeppelin Master); tirisfal.json 8516 part 1 (zeppelin to Vengeance Landing); subzone 4402 Vengeance Lift'),
(49506, 1, 495, 6, 0, 13, 'The Derelict Strand', 'South of Vengeance Landing the Bleeding Vale runs down to the Derelict Strand, where survivors of Stormwind''s North Fleet were driven ashore when the Forsaken destroyed their easternmost ships. Hungry, injured and poorly equipped, they have barricaded the beach behind cannons along its northern wall and fight with the fury of those who know they are going to die. Dark Ranger Lyana presses the siege from the vale, where Deathstalker Razael''s meat wagons sit stuck in the frozen ground and the bodies of both sides lie heaped across the field.', 'quest 11221 description (easternmost fleet destroyed; survivors barricaded on the Derelict Strand); quest 11270 description (remnants of Stormwind''s North Fleet; bodies); quest 11230 description (hungry, injured, ill equipped); quest 11232 description (cannons along the northern wall); Lyana npc_text 11586; Razael npc_text 11562 (ground frozen, meatwagons not going anywhere); zone_areas 4050, 4060 (Alliance and Forsaken corpses)'),
(49507, 1, 495, 7, 0, 13, 'Baleheim', 'Baleheim is a Winterskorn vrykul town in the hills west of Vengeance Landing, facing the Forsaken blockade at Balejar Watch beyond the lift. Its warriors come at the blockade without end, each screaming louder and swinging a bigger weapon than the last, and the abomination Sergeant Gorth holds the line against them. Champions such as Ulf the Bloodletter, Oric the Baleful and Gunnar Thorvardsson lead the charges, and from the town their leader, Bjorn Halgurdsson, rallies his people in the name of Queen Angerboda, promising that the val''kyr reward those who fight without fear.', 'quest 11282 description (vrykul across the blockade; heroes Ulf, Oric, Gunnar); quest 11283 description (town west of here); quest 11295 description (Gorth, an abomination, oversees the blockade beyond the lift); creature_text 24238 group 2 (For Queen Angerboda; the val''kyr will reward you); zone_areas 4001, 4403 (Bjorn Halgurdsson; Ulf, Oric, Gunnar at Balejar Watch)'),
(49508, 1, 495, 8, 0, 13, 'New Agamand', 'New Agamand is a Forsaken town in the western fjord and the home of the Society''s plaguebringers, who handle the practical side of deploying the plague and keep far better equipment than the soldiers at Vengeance Landing. Chief Plaguebringer Harris runs its laboratory, Plaguebringer Tillinghast dreams of a plague for every creature that lives, and the abomination maker Hacksaw Jenny stitches together whatever parts come her way, though most are spoiled by the plagues around her. Deathguards keep watch, and a bat handler keeps his bats ready at the edge of town.', 'Harris npc_text 11827 (plaguebringers practical; logistics of deploying the plague); quest 11304 description (better equipment there); Tillinghast npc_text 11724; quest 11279 description; Jenny npc_text 11884 and quest 11424 description (material contaminated by plagues); quest 12181 description (bat handler Tobias); zone_areas 3991'),
(49509, 1, 495, 9, 0, 13, 'Halgrind', 'Halgrind was a Dragonflayer village until the Forsaken took it. Its chieftain, Thorvald, fled west to a camp of his own, and the apothecaries have made the place a proving ground, spraying the vrykul left behind with plague from great tanks for weeks on end. The vrykul refuse to drop dead. Plagued tribesmen, rune-casters and handlers stagger among the plaguebringers, while from the abandoned vrykul tower at Ember Spear, just to the west, an Alliance scout watches and is certain the Forsaken are up to no good.', 'quest 11305 description (spraying Halgrind for weeks; chieftain fled west; patriarch of the Dragonflayer clan); quest 11202 description (plague tanks); Scout Knowles npc_text 11436 (abandoned vrykul tower; Forsaken up to no good); quest 11199 description (Ember Spear Tower west of Halgrind); zone_areas 3994 (Plagued Dragonflayer Tribesman, Handler, Rune-Caster; Forsaken Plaguebringer); 4260 Thorvald'),
(49510, 1, 495, 10, 0, 13, 'Westguard Keep', 'Westguard Keep crowns the western cliffs of the fjord, commanded by the dwarf Captain Adams. Its cannons fire on Skorn to the east, and its crossbowmen, gryphon riders and engineers have more work than hands. A pirate blockade in the Shattered Straits below sank all the keep''s ships, so Bombardier Petrov bombs the pirates from a goblin zeppelin shot down while ferrying for the Horde, whose owner, Harrowmeiser, complains that he is a prisoner. The Explorers'' League shelters its people and pack mules here, and a garrison is being readied for Fort Wildervar in the north.', 'Adams npc_text 11494 (garrison Fort Wildervar); quest 11187 reward text (dwarf of action); quest 11190 and Ely npc_text 11418 (shooting at Skorn); quest 11153 description and Petrov npc_text 11322 (ships sunk; blockade; zeppelin); Harrowmeiser npc_text 11328; quest 11224 description (Explorers'' League mules); zone_areas 3998'),
(49511, 1, 495, 11, 0, 13, 'Ember Clutch', 'Southeast of Westguard Keep lies the Ember Clutch, a forest that has burned since the Alliance arrived, its blaze spreading by some magic of its own. Proto-drakes nest among the flames. The keep''s soldiers fear the fire will surround them within weeks, but the Ember Clutch Ancients, who seek balance in all things, blame neither the drakes nor their whelps. The true culprits, they say, are the newly woken vrykul: the Dragonflayer handlers who keep a lair on the forest''s south side under their master, Skeld Drakeson.', 'quest 11157 description (ablaze since we arrived; perverse magic; surrounded within weeks); quest 11182 description (balance; newly awakened vrykul and Skeld Drakeson; lair on the south side); zone_areas 4048 (Proto-Drake Egg, Proto-Whelp, Proto-Drake, Dragonflayer Handler, Skeld Drakeson, Ember Clutch Ancient)'),
(49512, 1, 495, 12, 0, 13, 'Whisper Gulch', 'Whisper Gulch, north of Westguard Keep, is where most of the Explorers'' League went to dig, and something they found there drove them mad. The deranged explorers attack anyone who comes near, raving that they have learned the truth and that IT is coming, That Which Must Not Be Named. The ore of the gulch leaves a strange feeling in those who carry it, and a voice no one can place whispers that companions have turned traitor. Squeeg Idolhunter, once the explorers'' boss, keeps to a cave in the northwest corner.', 'quests 11218, 11224 descriptions (Explorers'' League went mad; ore is strange); quest 11218 reward text (strange feeling); quest 11240 description (Squeeg, old Explorers'' League boss, in the northwest cave); creature_text 23967 (Deranged Explorer lines); creature_text 29881 An Unknown Voice (whispers in the gulch); spell_area 27769 in area 4071 (always active)'),
(49513, 1, 495, 13, 0, 13, 'Steel Gate', 'Steel Gate is the Explorers'' League''s great excavation in the northwest of the fjord, a deep pit worked by excavators and archaeologists under Overseer Irena Stonemantle, who would like to finish and go home before the Rivenwood to the north grows any worse. Flying machines brought from Westguard Keep haul sacks of relics up to crane platforms and fight off the gargoyles that harry the site. Nearby, a small band of taunka watches the digging in anger: their Sage Mistwalker came following dreams of a wolf and believes the dwarves are carrying off artifacts of his people''s past.', 'quest 11176 description (flying machines from Westguard; Rivenwood getting worse; head back home); quest 11390, 11391 (relic sacks; gargoyles); quest 11286 description (dreams; small things digging; artifacts important to our past); quest 11287 description (vision of a wolf); zone_areas 3999 (Irena, Mistwalker, Skycloud, Moonleaf, Gjalerbron Gargoyle)'),
(49514, 1, 495, 14, 0, 13, 'The Rivenwood', 'The Rivenwood is a haunted forest north of Steel Gate. Riven widows, great spiders that keep their victims alive for their young, spin cocoons among the trees, darkclaw bats and Fanggore worgs hunt there, and gargoyles and the souls of vrykul drift through it. Something, most likely the Scourge, has agitated every creature in the wood. The taunka have learned to fear it: a hunting party that came this way with Sage Mistwalker lost most of its longrunners to the widows.', 'quest 11296 description and request text (riven widows; longrunners lost); quest 11154 description (darkclaw bats in the Rivenwood); quests 11317, 11322, 11323, 11325 descriptions (dreams; cave on the snowy northwestern edge); Ulfang npc_text 12112 and quest 11414 description (Garwal, the strange white worg); zone_areas 4054 (Riven Widow, Darkclaw Bat, Fanggore Worg, Gjalerbron Gargoyle, Vrykul Soul, Ulfang, Garwal)'),
(49515, 1, 495, 15, 0, 13, 'Skorn', 'Skorn is the Winterskorn fortress east of Westguard Keep and south of Camp Winterhoof, a place of towers lined with rune-casters, longhouses, barracks and, at the summit, a thane''s lodge with a great pyre before it. Its strange giants have lately woken and begun to spread, threatening Westguard and the taunka of Camp Winterhoof alike, and the keep''s cannons fire on it when they can. Those who have fought there warn that these vrykul can rise from the dead, a different undeath from the Scourge''s, unless their bodies are carved apart.', 'quest 11248 description (on our eastern border); quest 11256 description (to the south of Winterhoof; giants recently awakened and spreading); quests 11245, 11259 (towers lined with casters); quests 11247, 11258 (longhouses, barracks); quests 11249, 11260 (pyre in front of the thane''s lodge); quests 11246, 11257 descriptions (may rise from the dead; dismember); quest 11190 request text (pounding Skorn)'),
(49516, 1, 495, 16, 0, 13, 'Gjalerbron', 'Gjalerbron, its name spoken as if it began with Sh, is the great fortress of the vrykul in the north of the fjord, a forbidden place to the taunka. Cages line its paths, holding prisoners of every kind, and Scourge necrolords, wights and horrors move among the vrykul warriors and rune-casters. Beneath it, in the Waking Halls, rows of dormant vrykul stand waiting, and overhead the frost wyrm Glacion circles. At its northern end, the great chamber of the Winter''s Terrace opens onto the slopes of Gjalerhorn.', 'quest 11235 description (pronounced Sh); quest 11263 description (a forbidden place); quests 11231, 11265 (cages; prisoners); quests 11239, 11268 (Deathless Watchers, Fearsome Horrors, Putrid Wights; Waking Halls); quests 11432, 11433 (dormant vrykul in the Waking Halls); quest 11237 description (Glacion circles overhead); quest 11452 description (Winter''s Terrace, the large chamber on the north end); zone_areas 4006, 4065'),
(49517, 1, 495, 17, 0, 13, 'Camp Winterhoof', 'Camp Winterhoof is a taunka post in the foothills of Gjalerhorn, near the border with the Grizzly Hills. From a distance the taunka look like tauren, but they are sturdier and shaggier, and among them trust is earned, not given. Chieftain Ashtotem has decided they must leave for safer lands to the north before the fjord grows any more dangerous. Until then the camp gathers hippogryph down for the trek, culls the elementals of the hills one last time and prepares a final yeti hunt, while Celea Frozenmane''s wind riders watch the skies.', 'quest 11411 description (look like tauren, sturdier and shaggier; foothills of Gjalerhorn near Grizzly Hills) and reward text (trust is earned); Ashtotem npc_text 11688 (leave for safer lands to the north); Nokoma npc_text 11874; quest 11271 description (down for the long trek); quest 11311 description (cull the elementals one last time); quest 11275 description (yeti hunt, last before we leave); creature 24032 Celea Frozenmane, Wind Rider Master'),
(49518, 1, 495, 18, 0, 13, 'Fort Wildervar', 'Fort Wildervar stands in the snows of the far northeast, beyond Skorn and close to the border with the Grizzly Hills. It is being readied for the Alliance expeditionary force that will climb from here into the hills: craftsmen sew winter cloaks, miners dig ore for weapons and trappers bring in meat and furs, all dreading Captain Adams''s temper should the vanguard find anything unready. Homesteaders have come to settle, scholars study the iron dwarves at Giants'' Run, and a hippogryph whose feathers turn aside arrows circles over the fort.', 'quest 11406 description (far northeast beyond Skorn near Grizzly Hills; the captain''s temper); quest 11269 description (vanguard; cloaks); quest 11284 description (miners; weapons to carve a path into the Grizzly Hills); quest 11292 description (traps; meat and furs); zone_areas 4003 (Northrend Homesteader, Researcher Aderan, Prospector Belvar); quest 11418 description (arrows bounced off)'),
(49519, 1, 495, 19, 0, 13, 'The Frozen Glade', 'The Frozen Glade is the snowbound home of the frost nymphs, of whom the taunka have told tales for generations. Their queen forbids them to deal with outsiders, but the land is changing and many sisters are in danger, so Lurielle now welcomes visitors. A destructive force has turned the glade''s ice elementals against the nymphs, the Vibrant Glade to the southwest has thawed and driven its sisters mad, and the Twisted Glade to the west has filled with thornvine creepers and poisonous spores seeded by keepers who turned black of soul.', 'quest 11312 description and reward text (tales told by the taunka for generations; forbidden by our queen); quest 11302 description and reward text; quest 11313 description (ice elementals turned); quest 11314 description (Vibrant Glade thawed; sisters driven mad); quest 11316 description (Twisted Glade); quest 11319 description (blacksouled keepers seed spores)'),
(49520, 1, 495, 20, 0, 13, 'Kamagua', 'Kamagua is the village of the Kalu''ak tuskarr on the Isle of Spears, off the fjord''s southwestern coast, and Elder Atuik is its chieftain. The tuskarr live mostly from the sea, but this season the catch is modest, and survivors of Iskaal, a village to the east sacked by pirate slavers, keep pouring in. A gondola called the Ancient Lift climbs from the isle to the bluffs, and a great sea turtle carries travelers to Moa''ki Harbor in the Dragonblight.', 'Atuik npc_text 12364; quest 11456 description (fish catch modest; Iskaal survivors); quest 11458 description (Iskaal to the east); quest 11507 description (Ancient Lift to Kamagua); quest 12118 Travel to Moa''ki Harbor (Anuniaq); warcraft.wiki.gg/wiki/Kamagua (largest tuskarr village, Isle of Spears; turtle to Moa''ki Harbor); quest 11469 (Big Roy is killed for soap by the player during the pirate chain; not told)'),
(49521, 1, 495, 21, 0, 13, 'Scalawag Point', 'Scalawag Point, on Garvan''s Reef at the southwestern edge of the fjord, is the den of the Northsea Freebooters. Their ships lie at anchor, duelists fight for wagers under Taruk''s eye, and the witch doctor Zeh''gehn, whose speech only one or two can follow, divines traitors for the crew. Their captain, Mad Jonah Sterling, keeps to a cave west of the point and has set his crews raiding the Horde and Alliance fleets at once, and selling tuskarr as slaves, though the tuskarr die within days of leaving the cold.', 'quest 11463 description (Northsea Freebooters at Scalawag Point on Garvan''s Reef); Taruk npc_text 12173; quest 11473 description (Zeh''gehn, witch doctor; only one or two understand him); quest 11471 description (attacking both fleets; tuskarr die days after leaving); creature 24742 Mad Jonah Sterling (posarea 3989)'),
(49522, 2, 495, 1, 1, 13, 'Vice Admiral Keller', 'Vice Admiral Keller commands Valgarde, and he means to hold it. A man with a wife and three children back in Elwynn, he knows that if the port falls the Alliance loses its main supply line into Northrend, and he would rather die fighting than serve the Lich King. His people built the town with their own hands, he says, and have no plans ever to give it up. Not everyone admires him: at Westguard Keep, Captain Adams resents how many soldiers Keller kept at Valgarde and calls him an insufferable egomaniac.', 'quest 11243 description (wife and three kids in Elwynn; primary supply line); Keller npc_text 12097; Adams npc_text 11494 (insufferable egomaniac)'),
(49523, 2, 495, 2, 1, 13, 'Captain Adams', 'Captain Adams, a dwarf of action with a famous temper, commands Westguard Keep. His orders are to hold the keep and garrison Fort Wildervar for the march into the Grizzly Hills, and he has too few soldiers for both, a shortage he lays at Vice Admiral Keller''s feet. He sees threats on every side, from the burning Ember Clutch to the vrykul of Skorn and Gjalerbron and the Forsaken at Halgrind, and meets each of them head on. His advisor, Mage-Lieutenant Malister, quietly tries to temper his orders, with little success.', 'Adams npc_text 11494; quest 11187 reward text (Malister: tried to dissuade the captain; a dwarf of action); quest 11406 description (famous for his temper); quests 11157, 11199, 11235, 11248 descriptions; quest 11291 request text (it sure wasn''t because of Keller)'),
(49524, 2, 495, 3, 2, 13, 'High Executor Anselm', 'High Executor Anselm commands Vengeance Landing. He has served in the military all his life, in many wars under many banners, but always in other people''s battles. Not this time: every Forsaken soldier at the landing has come for one reason, to see Arthas killed, and the Alliance are merely an obstacle to be crushed on the way. He prizes discipline over heroics and has little patience for arrogant newcomers in shiny armor who think themselves above the chain of command.', 'Anselm npc_text 11796; quest 11221 description (Alliance but an obstacle); quest 11270 reward text (arrogant fool in shiny armor; chain of command)'),
(49525, 2, 495, 4, 1, 13, 'Thoralius the Wise', 'Thoralius the Wise is a draenei seer at Valgarde. The Explorers'' League may dig up pieces of the past, he says, and the vice admiral may wring knowledge of the present out of his enemies by force, but the truth lies with the spirits. With the proper reagents, burned in his incense and breathed in, he can look into the spirit world, where he holds that the past, present and future of Northrend reside. His reagent pouch, unfortunately, went down with a ship in Daggercap Bay.', 'quest 11333 description; creature_text 23975 (Fire grant me vision; inhales the smoke); creature display 21947 (draenei male)'),
(49526, 2, 495, 5, 2, 13, 'Chieftain Ashtotem', 'Chieftain Ashtotem leads the taunka of Camp Winterhoof. He speaks plainly to outsiders: among his people trust is earned, not given. The dead walk the land and even arrive on ships from across the great ocean, the vrykul have woken in their fortresses, and he has decided that his people must leave for safer lands to the north, though some of his warriors would rather stand and fight. Until the camp departs he accepts any help with its preparations, and sends what fighters he can against the vrykul of Skorn and Gjalerbron.', 'Ashtotem npc_text 11688; quest 11411 reward text (trust is earned, not given); Ahota Whitefrost npc_text 13035 (stand and fight); quests 11256, 11263 descriptions; Nokoma npc_text 11874 (Ashtotem''s decision)'),
(49527, 2, 495, 6, 0, 13, 'Queen Angerboda', 'Angerboda is queen of the vrykul and wife of King Ymiron, who lies dormant in the Winter''s Terrace at the northern end of Gjalerbron. With necrolords of the Scourge at her side she drives a ritual to wake him, demanding ever more sacrifices and calling on her husband-king to rise and reign again with the might of the Lich King behind him. Her patience is wearing thin: the ritual moves too slowly, and the help the Scourge promised has not sped it.', 'creature_text 24023 group 2 (yells: more sacrifices; my husband-king will awaken; with the might of the Lich King; your master promised); quests 11452, 11453 descriptions; creature 24023 and 29393 King Ymiron at Gjalerhorn (posarea 4065)'),
(49528, 2, 495, 7, 0, 13, 'Elder Atuik', 'Elder Atuik is chieftain of the Kalu''ak of Kamagua. His people are peaceful and live mainly from the sea, hunting on land only in times of great need, and this is such a time, for pirates have sacked the nearby village of Iskaal and its survivors keep arriving. Atuik remembers the tales of Issliruk, the spirit of war, a silver eagle who fought a hundred worgs to save his young, and he is ready to set the old peace aside to defend his kin.', 'Atuik npc_text 12364; quest 11456 description; quest 11457 description (Issliruk); quest 11458 description (cast our peaceful ways)'),
(49529, 3, 495, 1, 1, 13, 'Valgarde Besieged', 'Newcomers to Valgarde are greeted by the dwarf Macalroy, who doubts the green recruits Fordragon sent can hold the port much longer and sends anyone better equipped on to Vice Admiral Keller. Keller lays it out plainly: if Valgarde falls, the Alliance loses its main supply line into Northrend. The town had stood a month when malformed giants appeared as if from thin air. An archaeology team was lost, townsfolk were dragged away to the ruins to the north, and the defenders at the gate face wave after wave of raiders and their worgs.', 'quest 11228 description and reward text; quest 11243 description and objectives (Dragonflayer Invaders, Worgs); quest 11244 description'),
(49530, 3, 495, 2, 1, 13, 'The Wyrmskull Tablets', 'Beltrand McSorf of the Explorers'' League was the only one of his crew to make it back to Valgarde when the monsters struck their dig at Wyrmskull. The team had been on the brink of an archaeological breakthrough, and he will not give it up: the artifacts they uncovered must be found, and any of his crew who might still be alive with them. The ruins now lie in the hands of the Dragonflayer vrykul, and McSorf asks anyone bound that way to look first for Pulroy, the last of his team he saw.', 'quest 11273 description; quest 11274 description (beast-men in the ruins)'),
(49531, 3, 495, 3, 2, 13, 'The Last of the North Fleet', 'The Forsaken have destroyed the Alliance''s easternmost fleet, but the survivors of Stormwind''s North Fleet have barricaded themselves on the Derelict Strand south of Vengeance Landing and held out far longer than anyone expected. High Executor Anselm wants it finished. In the lands of the Lich King the dead are a weapon that may rise at any moment, so the corpses west of the town are put to the torch, and his officers in the field, Dark Ranger Lyana and Deathstalker Razael, are pressed for their reports.', 'quest 11270 description; quest 11221 description'),
(49532, 3, 495, 4, 0, 13, 'The New Plague', 'Ever since Arthas condemned them to undeath, the Royal Apothecary Society has worked on a plague of its own, one meant to devour all flesh, living, dead or undead, and the apothecaries have brought it to Northrend to deliver to the Scourge''s doorstep. Not everything has gone to plan: the Alliance intercepted a ship carrying their latest strain, and the strains sent from the Undercity keep failing. At Westguard Keep, meanwhile, scouts report the Forsaken up to something at the Dragonflayer village of Halgrind.', 'quest 11167 description; quest 11199 description; creature_text 24126 group 6 (strains from Undercity keep failing)'),
(49533, 3, 495, 5, 0, 13, 'The Slumbering King', 'Word from the north troubles Westguard Keep and Camp Winterhoof alike. At Gjalerbron, the great fortress of the vrykul in the north of the fjord, the giants have woken and are performing an awakening ritual fed by living sacrifices kept in cages. Captain Adams and Chieftain Ashtotem each send fighters to cull the vrykul before they finish whatever they are doing, while Father Levariol and Greatmother Ankha plead for the prisoners to be freed, whoever they are, lest the ritual wake something even more evil.', 'quests 11235, 11263 descriptions; quests 11231, 11265 descriptions'),
(49534, 3, 495, 6, 0, 13, 'The Relics of Shield Hill', 'Tuskarr hunters returning to Kamagua swear that the dead have risen along an old hunting trail by Shield Hill, an ancient vrykul burial ground on the bluffs, and are out for blood. Elder Atuik sent Orfus of Kamagua, one of his strongest warriors, with Lunk-tusk to find out why. The undead attacked them as they neared the graves, and the two were parted. Now Orfus waits at the Ancient Lift for anyone brave enough to search the desecrated graves for clues.', 'quest 11504 description; quest 11573 description (Lunk-tusk); quest 11507 reward text (one of our strongest warriors); zone_areas 4057 (Risen Vrykul Ancestor, Blood Shade)'),
(49535, 3, 495, 7, 0, 13, 'The Iron Dwarves', 'Strange dwarves of living iron have appeared in the eastern fjord. At Giants'' Run, a rocky plateau southeast of Fort Wildervar, iron rune stonecallers and binders coax stone giants out of the ground and carve runes into them, as if to make them into weapons. On the high bluffs farther south they have driven the Explorers'' League from its dig sites at Ivald''s Ruin and Baelgun''s Excavation Site, and rather than digging up the relics there, they are burying them, as though no one must ever find what lies below.', 'quest 11346 description (Giants'' Run southeast; coaxing giants; carving runes; weapons); quest 11350 description; quest 11474 description and reward text (pushed out of Ivald''s Ruin and Baelgun''s; burying the sites); quest 11477 description');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(49501, 1, 0, 255, 'Lord Irulon was waiting for a sacred blade. Argent soldiers died in the Plaguelands to see it cleansed by the light of dawn, only for it to be hurled into a den of the fallen deep in the Utgarde Catacombs, guarded by the unmerciful dead. The envoy Ares the Oathbound, sent after it, did not live to carry it out. Lord Tirion Fordring himself is to wield it as the Crusade works toward Icecrown, and Irulon calls him their greatest hope.', 'quest 11288 description (forces decimated in the Plaguelands; cleansed by the light of dawn; hurled into the den of the fallen); quest 11289 description (Ares dies) and reward text (wielded by Tirion; Crusade works toward Icecrown; greatest hope)'),
(49504, 1, 0, 255, 'Payback came from the vrykul''s own weapons. With Harpoon Master Yavus slain and a stolen harpoon control mechanism in hand, an Alliance gunner seized one of Nifflevar''s guns and rained fire on Wyrmskull below, burning its longhouse, dockhouse and stores and cutting down many of its dragon riders.', 'quest 11430 description and reward text (Yavus responsible for most attacks; slain); quest 11421 description and reward text'),
(49504, 2, 0, 255, 'Lieutenant Icehammer then built a harpoon controller of his own and tested it on the gunner, who was flung from Nifflevar''s largest gun all the way into Valgarde. Guard Captain Zorek called it insane, but word came soon after that Ingvar, the Dragonflayer leader, was furious.', 'quest 11436 description and reward text'),
(49504, 3, 0, 255, 'Scribe Seguine of Ghostblade Post would not let vrykul learning burn with the village. Ahead of the Forsaken assault, the three sagas written by the bard Helgus were carried out of Nifflevar: the Saga of the Twins, the Saga of the Winter Curse and the Saga of the Val''kyr, and Seguine set to translating them.', 'quest 11423 description and reward text'),
(49507, 1, 0, 255, 'Bjorn would not leave his town, so Lydell''s assassins laid an ambush to the northwest and gave him a reason to. He was a known hothead, and a crude insult in his own tongue about his mother sent him charging out after the one who read it, straight into the trap. He never saw it coming.', 'quest 11303 description (leader stays in town); quest 12481 description and reward text; creature_text 24238 groups 0-1'),
(49511, 1, 0, 255, 'Captain Adams ordered the eggs and whelps destroyed, and the enraged proto-drakes struck at the keep in return. Mage-Lieutenant Malister, who had argued against the order, saw no choice but to kill three of the beasts. He called them noble creatures and hoped the young drakes would not remember the Alliance''s shameful deeds.', 'quest 11157 reward text; quest 11187 description and reward text; quest 11188 description and reward text'),
(49511, 2, 0, 255, 'The Forsaken tried their plague here as well. Plaguebringer Tillinghast sprayed the eggs and lured a drake down to eat plagued meat, dreaming of a strain that would work on any creature. The whelps only glowed green, the drake failed to dissolve, and Tillinghast wept over his ruined dreams.', 'quest 11279 description and reward text; quest 11280 description and reward text'),
(49513, 1, 0, 255, 'Irena''s betrothed, Explorer Jaren, went west to the Chillmere Coast after rumored artifacts and found the Scourge instead, turning murlocs into mur''ghouls with scourging crystals. A controller taken from one of the dead brought the crystals'' shields down so they could be smashed, and Jaren sent his love back to Irena with word that he was safe.', 'quest 11393 description; quest 11394 description; quest 11395 reward text; quest 11396 description and reward text'),
(49514, 1, 0, 255, 'In a cave on the wood''s snowy northwestern edge the worg Ulfang lies trapped, and he has been calling out in the dreams of Sage Mistwalker and Watcher Moonleaf. To those who reach him in worg guise he tells how, at the last full moon, a strange white worg named Garwal came from the north and, with the help of Ulfang''s own brothers, took his pack from him. There is something unnatural about Garwal, he says.', 'quests 11317, 11322 descriptions (dreams); quests 11323, 11325 descriptions and reward text (cave on the snowy northwestern edge; trapped); quests 11414, 11415 descriptions (last full moon; strange white worg from the north; once-brothers; something unnatural); Ulfang npc_text 12112; creature_template 24261 faction 1924 (hostile to players without the disguise)'),
(49514, 2, 0, 255, 'Ulfang''s treacherous brothers were hunted down, and with the eyes of the eagle Talonshrike his enemy could be seen at last. Garwal was no worg: confronted, he threw off his disguise and stood revealed as a worgen. Ulfang leads his pack again, though his friends were left puzzled that the creature had come south from the Grizzly Hills.', 'quests 11414-11417 descriptions; creature_text 24277 (Enough of this charade!); creature 24278 Garwal - Worgen Transform; quests 11324 and 11326 reward text'),
(49515, 1, 0, 255, 'A dragonskin scroll found at Skorn showed a vrykul thane rising into the heavens among angelic figures, a dark shape looming behind. Father Levariol and Greatmother Ankha read it the same way: the vrykul may have a way to transcend death, at least the worthy among them, and the Winterskorn thane slain beside his pyre had proved himself unworthy.', 'quests 11249 and 11260 descriptions and reward text'),
(49518, 1, 0, 255, 'Seen through its own eyes by way of Researcher Aderan''s feathered charm, the hippogryph the settlers call Steelfeather was found to keep a nest of hatchlings close to the fort. Their ''he'' was a she all along, Gil Grisert conceded, and the fort and its new neighbor would get along just fine if Trapper Jethan would only stop trying to make a trophy of her.', 'quest 11418 description and reward text'),
(49519, 1, 0, 255, 'Keeper Witherleaf, the mightiest of the blacksouled keepers, has fallen, and with him the strongest of the powers raising horrors from the waters and soil of the Twisted Glade. Lurielle grieves for the keepers, who were once the sisters'' brothers and closest friends, but for the first time she sees hope for the glades.', 'quest 11428 description and reward text'),
(49521, 1, 0, 255, 'An outsider in pirate disguise, vouched for by a goblin, has been working up through the crew. Zeh''gehn''s croaker named the rat among them: Crowleg Dan, who boasted that he had joined the Southsea pirates before he was cut down. Handsome Terry mourned an old friend who also owed him money.', 'quest 11509 (Grezzix''s cabin boy brings you in); quests 11473, 11459, 11476 descriptions; creature_text 24713; quest 11479 reward text'),
(49521, 2, 0, 255, 'Annie Bonn, the crew''s second in command, then made her own move. She had Jonah Sterling killed in his hideout and, as word of his death spread, took the Freebooters for herself, promising to end their attacks on the infiltrator''s allies, and hoping no one would learn she had arranged it.', 'quest 11471 description and reward text; Annie Bonn npc_text 12187'),
(49522, 1, 0, 255, 'When the vrykul harpooned his scouts and left them for dead in the forest, Keller saw it for what it was, a savage display meant to send Valgarde running in fear. It failed, he declared, and he turned the town from defense to attack, set on showing the giants what it means to make war on the Alliance.', 'quest 11244 description and reward text'),
(49524, 1, 0, 255, 'A dragonskin map, sniffed out by the landing''s plaguehounds, showed him what he faced: Dragonflayer and Winterskorn villages around the fjord, and Vengeance Landing marked for death with a great skull. Forsaken records showed no sign of the vrykul in their lands for centuries, yet here they were just as the Forsaken moved against Arthas, and Anselm resolved to strike first, at Baleheim.', 'quest 11253 reward text; quest 11254 description and reward text; quest 11295 description; quests 11227 and 11253 descriptions (plaguehounds to sniff out enemy scouts; the hound leads to the scroll)'),
(49525, 1, 0, 255, 'With his pouch recovered he breathed the smoke and saw something that left him shaking. The spirit world, he says, has fallen under the sway of the Lich King: val''kyr, creatures of pure nightmare, now stand watch over the realm of the elements, guarding a terrible secret at Wyrmskull.', 'quest 11333 reward text; quest 11343 description'),
(49525, 2, 0, 255, 'In the spirit world at Wyrmskull stood a vrykul couple of long ago over a newborn child, which they took as a sign that they too were cursed. The father would be rid of it before King Ymiron learned of it, the mother begged to hide it somewhere far away, and Thoralius could not see why these ancient figures looked like the vrykul now attacking Valgarde.', 'creature_text 24314, 24315 (phase 2 at Wyrmskull); quest 11343 reward text'),
(49525, 3, 0, 255, 'The visions reached back fifteen thousand years. At Nifflevar the spirits showed Ymiron blaming the titans for cursing his people with malformed children, renouncing the old gods and decreeing that every such infant die at birth. The children, Thoralius concluded, were human. There was no extinct missing link: the vrykul are the progenitors of humanity.', 'quest 11344 description (visions dating back 15,000 years) and reward text; creature_text 24321 (Ymiron''s decree, phase 2 at Nifflevar)'),
(49527, 1, 0, 255, 'Queen Angerboda fell in the Winter''s Terrace, cut down beside the sleeping husband she had labored so long to wake, and her calls for more sacrifices fell silent at last.', 'creature 24023 Queen Angerboda (guid 42162, map 571, phase 1, 150 second respawn; posarea 4065); smart_scripts 24023 (on death summons the Lich King 29394)'),
(49528, 1, 0, 255, 'The slavers who raided Iskaal had lost their minds and slaughtered all their captives. With spear tips carved from chimaera horn and the totem of Issliruk raised, Atuik sent help to Iskaal to cut them down, and the Kalu''ak swore themselves forever in their avengers'' debt.', 'quest 11457 description; quest 11458 description and reward text'),
(49529, 1, 0, 255, 'The soldiers rescued from Wyrmskull Village gave the enemy a name. The giants call themselves vrykul, and the tribe that has taken the village answers to a mystic named Yanis, himself the underling of another vrykul, Ingvar the Plunderer.', 'quest 11255 reward text'),
(49529, 2, 0, 255, 'From Yanis''s cave came the Dragonflayer battle plans. They showed the fjord dotted with vrykul villages and a different tribe readying an assault on Westguard Keep, which had not been heard from in days. Keller sent the plans west by gryphon to warn Captain Adams.', 'quest 11290 description and reward text; quest 11291 description'),
(49529, 3, 0, 255, 'Scout Valory''s search of Wyrmskull found nearly everyone slain or taken. On the hill above, Defender Mordun stood among the bodies of his best men. The vrykul, he warned, are fearless and yearn for a death in battle, but there is one they esteem, Ingvar, and bringing him down might break their spirit.', 'quest 11251 description and reward text; Mordun npc_text 11667; quest 11252 description (source only)'),
(49530, 1, 0, 255, 'Pulroy was found dead with his journal clutched in his hand, and Zedd dead too, about to be fed to the worgs. Glorenfeld still lived in the Utgarde Catacombs, but Daegarn had been taken deeper by the Dragonflayer chieftain as a sacrifice to the Dread King, with the cipher for the tablets hidden in his beard, as dwarves do.', 'quest 11273 reward text; quest 11274 description and reward text; quest 11276 reward text'),
(49530, 2, 0, 255, 'The vrykul had searched the beard first. The cipher had passed to Oluf the Violent, chieftain of the gladiators, and only by beating his fighters in the Ring of Judgement could he be drawn out and the cipher won back. Glorenfeld puzzled for a moment over Daegarn''s talk of something judging the bouts, then counted the cost: tablets and cipher recovered, two dwarves dead.', 'quest 11299 reward text; quest 11300 description and reward text; creature_text 23931'),
(49530, 3, 0, 255, 'McSorf''s first look at the tablets suggested that whatever once lived at Wyrmskull was an ancestor of humankind, perhaps wiped out by the vrykul. Unable to read them even with the cipher, he sent everything on to the League''s cryptographer, Stanwad, at the outpost on the southeastern bluffs.', 'quest 11278 reward text; quest 11448 description'),
(49530, 4, 0, 255, 'Stanwad was not impressed. After all the lives spent to recover it, the great discovery turned out to be an ancient recipe for tundra stew: pictures of common vegetables beside a mouth chewing on them, a code no one needed a cipher to break.', 'quest 11448 reward text'),
(49531, 1, 0, 255, 'The cannons on the strand kept the Forsaken at bay, so orders went to Captain Harker''s ships offshore, the Windrunner, the Queen''s Reprisal and the Oblivion, to silence them. Approaching through the reefs, the ships were themselves boarded by North Fleet marines and had to be won back before their guns could fire.', 'quest 11221 reward text; quest 11229 description; quest 11230 description and reward text'),
(49531, 2, 0, 255, 'Smoke flares marked the cannons on the northern wall, the ships'' guns cleared the way, and Lyana''s troops advanced. In the confusion the Alliance leaders, Captain Olster, Lieutenant Celeyne and Sergeant Lorric, were hunted down behind their own lines, and Lyana declared the victory beyond dispute.', 'quest 11232 description; quest 11233 description and reward text'),
(49531, 3, 0, 255, 'Anselm had no time to celebrate. Prince Keleseth of the San''layn came to the landing with an offer from Arthas: abandon Sylvanas''s childish rebellion and command armies far greater, or be driven out by the vrykul, who had cast their lot with the Lich King. Anselm answered with his archers. The prince shrugged off the volley, drank in the souls of the dying and vowed to return once Utgarde''s armies had fallen upon the landing.', 'quest 11234 reward text (visitors from the west); creature_text 24041 groups 0-7; creature_text 23780 groups 1-3; smart_scripts 23780 / 2378000'),
(49532, 1, 0, 255, 'Apothecary Lysander''s strain went on from Vengeance Landing to New Agamand, where Chief Plaguebringer Harris brewed a version made for vrykul from the blood of Thorvald, Halgrind''s fled chieftain. Sprayed on the plagued villagers, it did not melt them as he had hoped, but it turned them against one another, and Harris, ever practical, declared the research a success.', 'quest 11304 description; quest 11305 description; quest 11307 description and reward text; quest 11308 description'),
(49532, 2, 0, 255, 'After what he called an eternity of failure, Chief Plaguebringer Harris of New Agamand announced perfection at last: a strain to tear down the very fabric of life. It had no proper name yet, so he called it blight, and sent a specimen by bat to Venomspite in the Dragonblight.', 'quest 12181 description and request text'),
(49532, 3, 0, 255, 'Scout Knowles found the Forsaken spraying plague on Halgrind''s vrykul and recovered an apothecary''s package from the village. At the keep the tipsy amateur alchemist Peppy Wrongnozzle mixed it into a vaccine and tried it on a vrykul prisoner, who melted. She feared she had perfected the plague for the Forsaken, and Captain Adams heard the news in disgust.', 'quest 11202 reward text; quests 11327, 11328 descriptions; quest 11330 description and reward text; quest 11331 reward text'),
(49532, 4, 0, 255, 'Adams would not let a Forsaken super plague melt his soldiers where they stood. A gryphon rider loaded with bombs flew over New Agamand and blew its plague tanks to smithereens, and the gleeful captain declared it a lesson for the Forsaken.', 'quest 11332 description and reward text'),
(49533, 1, 0, 255, 'The Scourge is at Gjalerbron too. Necromancers work beside the vrykul, plainly meaning to bring them into the Lich King''s fold, under a leader called Necro Overlord Mezhen, who keeps to a platform at the rear of the fortress.', 'quests 11236, 11264 descriptions'),
(49533, 2, 0, 255, 'Plans taken from the vrykul revealed an attack to be led by the frost wyrm Glacion, which circles overhead, at the command of Wyrmcaller Vile. Blowing the wyrmcaller''s own horn called the beast down to its death, and the horn was carried away so it could never fall into the wrong hands again.', 'quests 11237, 11266 descriptions; quests 11238, 11267 descriptions and reward text'),
(49533, 3, 0, 255, 'Papers dropped by Mezhen told what the ritual was for. Queen Angerboda was struggling to wake her husband, King Ymiron, in the Winter''s Terrace. She was slain there, but the Lich King himself carried Ymiron off, which no one liked the sound of. Still, the vrykul plans had taken a heavy blow, and time had been bought.', 'quests 11452, 11453 descriptions and reward text'),
(49534, 1, 0, 255, 'The clues pointed to pirates. The Northsea Freebooters had plundered the burial mounds, and Orfus resolved to recover what they had stolen and return it to the graves, so that the spirits might rest and his people know peace once more.', 'quest 11504 reward text; quest 11507 description (war with the Northsea Freebooters, shown as 11504 is turned in)'),
(49534, 2, 0, 255, 'The goblin Grezzix, who smuggled Orfus''s champion into Scalawag Point, wanted nothing to do with the relics, and inside, Silvermoon Harry warned that everyone who had touched them was now dead, missing or both. The pirates were plainly afraid of what they had taken.', 'quest 11508 reward text; quest 11509 description and reward text'),
(49534, 3, 0, 255, 'All four relics were recovered, from a derelict ship, a Forsaken destroyer, a crew of ghosts and a madman''s den, and laid back in the mounds: the Frozen Heart of Isuldof, the Shield of the Aesirites, the Staff of Storm''s Fury and the Ancient Armor of the Kvaldir. It came too late. The dead warned that the Kvaldir return out of the mist and fog, and Orfus feared they would show the Kalu''ak no mercy.', 'quests 11511, 11512, 11519, 11567 descriptions; quest 11568 description and reward text; creature_text 24874-24877'),
(49534, 4, 0, 255, 'Elder Atuik took the warning gravely. The Kalu''ak of Kamagua now prepare for battle and send word to their kin across the sea of what is coming, hoping it is not already too late.', 'quest 11572 description and reward text'),
(49535, 1, 0, 255, 'The runes drove the giants north and west toward a lodestone the binders had made: Megalith, the mightiest of the runed giants, created by Binder Murdis to lead them. Megalith was felled in the foothills of Frostblade Peak, and with his last breath urged his brethren to let nothing keep them from the Stoneforge, a name no one knew, though it sounded like something of the titans.', 'quests 11355, 11365 reward text (north and west); quests 11358, 11366 reward text; quests 11359, 11367 descriptions and reward text; creature_text 24371'),
(49535, 2, 0, 255, 'Walt of the Explorers'' League built a false iron construct to slip back into Baelgun''s. Sent into a thundering cave around a titan statue, it brought back word that the iron dwarves are at work in the Storm Peaks, along with a name Walt had never heard: Loken. He sent the news on to the League''s base in the Dragonblight.', 'quests 11475, 11483-11491 descriptions; quest 11495 description and reward text');
